function calcularZAVIC(respuestas) {
  /*
   * respuestas: array de objetos { id: 'Z01', mas: 'A', menos: 'C' }
   * Retorna: { L, M, I, C } puntajes normalizados 0-100
   *          + { veredicto, descarte_motivo }
   */
  const MAPA = {
    Z01: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z02: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z03: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z04: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z05: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z06: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z07: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z08: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z09: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z10: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z11: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z12: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z13: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z14: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z15: { A: 'L', B: 'M', C: 'I', D: 'C' }
  };

  const POSITIVAS = ['L', 'M'];
  const NEGATIVAS = ['I', 'C'];
  const scores = { L: 0, M: 0, I: 0, C: 0 };

  respuestas.forEach(function(r) {
    var dim_mas   = MAPA[r.id][r.mas];
    var dim_menos = MAPA[r.id][r.menos];
    // MÁS en dimensión positiva = suma 2
    if (POSITIVAS.indexOf(dim_mas) !== -1) scores[dim_mas] += 2;
    // MENOS en dimensión negativa = suma 2 (candidato la rechaza)
    if (NEGATIVAS.indexOf(dim_menos) !== -1) scores[dim_menos] += 2;
  });

  // Normalizar a 0-100
  var normalizado = {};
  Object.keys(scores).forEach(function(k) {
    normalizado[k] = Math.round(scores[k] / 30 * 100);
  });

  // Evaluar cortes
  var descarte_motivos = [];
  if (normalizado.L < 40) descarte_motivos.push('Legalidad baja: ' + normalizado.L);
  if (normalizado.M < 40) descarte_motivos.push('Moral baja: ' + normalizado.M);
  if (normalizado.I >= 70) descarte_motivos.push('Indiferencia alta: ' + normalizado.I);
  if (normalizado.C >= 40) descarte_motivos.push('Corrupcion elevada: ' + normalizado.C);

  var alertas = [];
  if (normalizado.L >= 40 && normalizado.L < 70) alertas.push('Legalidad en zona de alerta: ' + normalizado.L);
  if (normalizado.M >= 40 && normalizado.M < 70) alertas.push('Moral en zona de alerta: ' + normalizado.M);
  if (normalizado.I >= 40 && normalizado.I < 70) alertas.push('Indiferencia en zona de alerta: ' + normalizado.I);
  if (normalizado.C >= 21 && normalizado.C < 40) alertas.push('Corrupcion en zona de alerta: ' + normalizado.C);

  var veredicto = descarte_motivos.length > 0 ? 'DESCARTE' :
                  alertas.length > 0        ? 'ALERTA'   : 'PASA';

  return {
    puntajes: normalizado,
    veredicto: veredicto,
    descarte_motivos: descarte_motivos,
    alertas: alertas
  };
}
